    fn parse_balance(&self, response: Option<&crate::value::Dict>) -> Option<crate::value::Dict> {
        let mut response: Value = response.map_or(Value::Null, Value::from);
        //
        //     {
        //         "USDC": {
        //             "available": "120",
        //             "locked": "0",
        //             "staked": "0"
        //         }
        //     }
        //
        let balanceKeys: Vec<&str> = response.as_map().map(|__m| __m.keys().map(String::as_str).collect()).unwrap_or_default();
        let mut result: indexmap::IndexMap<String, Value> = ({
            let m = indexmap::IndexMap::new();
            m
        });
        {
                        let mut i: i64 = 0;
            let mut __for_first_13: bool = true;
            while { if !__for_first_13 { i += 1; } __for_first_13 = false; i < (balanceKeys.len() as i64) } {
            let id: Option<&str> = balanceKeys.get(i as usize).copied();
            let code: Option<String> = self.safe_currency_code(id.as_deref(), None);
            let balance: crate::value::Dict = self.safe_dict_t(&response, Value::from(id.as_deref()));
            let mut account: indexmap::IndexMap<String, Value> = std::sync::Arc::unwrap_or_clone(self.account());
            let locked: Option<String> = self.safe_string_k_opt(&balance, "locked", &[]);
            let staked: Option<String> = self.safe_string_k_opt(&balance, "staked", &[]);
            let used: Option<String> = crate::precise::Precise::stringAdd(&locked, &staked).as_str().map(str::to_owned);
            account.insert("free".into(), self.safe_string_k(&balance, "available", &[]));
            account.insert("used".into(), used.map(Value::from).unwrap_or(Value::Null));
            if (code.is_some()) {
                result.insert(code.as_deref().unwrap_or("null").to_string(), Value::Map(account));
            }
        }
        }
        return Some(self.safe_balance(Value::Map(result)));

    None
}
